package dnsmasq

import (
	"fmt"
	"net"
	"sort"
	"strings"
)

// rendererHeader documents generated files for anyone who reads them on
// disk; it is a comment, not part of either file format's grammar.
const rendererHeader = "# Generated by internal/dnsmasq. Do not edit by hand; this file is\n" +
	"# overwritten on every CDN toggle and re-read by dnsmasq's in-container\n" +
	"# watcher (KTD7).\n"

// EnabledDomains is the one shared filter+flatten step Generate (the live
// dnsmasq config), GenerateBYODExport (byod.go), and U6's nginx allow-list
// rendering all build on -- KTD6 requires every consumer to render from
// the same in-memory model, so this is the single place "which domains are
// active" is decided. Exported so internal/cdn's toggle can derive nginx's
// allow-list entries from the identical exact/wildcard split dnsmasq uses,
// rather than a second, independently-arrived-at domain list.
func EnabledDomains(platforms []Platform, enabledNames []string) (exact, wildcard []string) {
	enabled := make(map[string]struct{}, len(enabledNames))
	for _, n := range enabledNames {
		enabled[strings.ToLower(strings.TrimSpace(n))] = struct{}{}
	}

	exactSet := make(map[string]struct{})
	wildcardSet := make(map[string]struct{})
	for _, p := range platforms {
		if _, ok := enabled[strings.ToLower(p.Name)]; !ok {
			continue
		}
		for _, d := range p.Domains {
			switch d.Kind {
			case DomainWildcard:
				wildcardSet[d.Base] = struct{}{}
			default:
				exactSet[d.Base] = struct{}{}
			}
		}
	}

	// Drop exact entries that a wildcard already covers: nginx's map{hostnames}
	// rejects having both cdn.example.com and .cdn.example.com for the same
	// base, and the wildcard form is a strict superset.
	for k := range wildcardSet {
		delete(exactSet, k)
	}
	exact = setToSortedSlice(exactSet)
	wildcard = setToSortedSlice(wildcardSet)
	return exact, wildcard
}

func setToSortedSlice(set map[string]struct{}) []string {
	out := make([]string, 0, len(set))
	for k := range set {
		out = append(out, k)
	}
	sort.Strings(out)
	return out
}

// Generate renders both files dnsmasq needs for the given enabled-platform
// set (R9): addnHosts is the exact-hostname --addn-hosts content (hot-
// reloadable via SIGHUP), wildcardConf is the --address=/domain/ip content
// for wildcard subdomains (restart-only -- see DomainKind's doc comment).
// cacheServerIP is the operator-configured LAN IP clients should resolve
// these CDN hostnames to; it is the one genuinely untrusted runtime input
// here (the platform/domain data itself is a pinned vendored snapshot), so
// it is validated as a real IP literal before being written into either
// file's grammar.
func Generate(cacheServerIP string, platforms []Platform, enabledNames []string) (addnHosts, wildcardConf string, err error) {
	if net.ParseIP(cacheServerIP) == nil {
		return "", "", fmt.Errorf("cacheServerIP %q is not a valid IP address", cacheServerIP)
	}

	exact, wildcard := EnabledDomains(platforms, enabledNames)

	var hosts strings.Builder
	hosts.WriteString(rendererHeader)
	for _, d := range exact {
		fmt.Fprintf(&hosts, "%s %s\n", cacheServerIP, d)
	}

	var wc strings.Builder
	wc.WriteString(rendererHeader)
	for _, d := range wildcard {
		// --address's domain matching already covers subdomains of the
		// given domain (confirmed against dnsmasq's own docs), so no
		// wildcard token is written here -- just the bare base domain.
		fmt.Fprintf(&wc, "address=/%s/%s\n", d, cacheServerIP)
	}

	return hosts.String(), wc.String(), nil
}
